def fizzbuzz(n):
    out = []
    for k in range(1, n + 1):
        if k % 4 == 0 and k % 6 == 0:
            out.append('AB')
        elif k % 4 == 0:
            out.append('A')
        elif k % 6 == 0:
            out.append('B')
        else:
            out.append(str(k))
    return out

