def bfs(adj, s):
    seen, order, q = {s}, [], [s]
    while q:
        u = q.pop(0)
        order.append(u)
        for v in sorted(adj.get(u, [])):
            if v not in seen:
                seen.add(v)
                q.append(v)
    return order

